function TouchInputSwitchable:__init()
    self.controller = nil

end


function TouchInputSwitchable:__delete()
    self.OnSwitch = nil
end



function TouchInputSwitchable:Init( switchablePlayerController_, playerInputSwitcher_  )

    self.switchablePlayerController = switchablePlayerController_ -- todo: 删了它
    self.playerInputSwitcher = playerInputSwitcher_
    ---
    DreamSpaceLuaUtils.StopCoroutine( self.co_0 )
    self.co_0 = cs_coroutine.start(self.DelayInit, self)
end 



function TouchInputSwitchable:DelayInit() 

    -- must after Awake()
    self.mCamera = DreamSpaceCamera.GetMainCamera()
    assert( not isNull(self.mCamera:GetComponent(typeof(CinemachineBrain))) )

    self.joystick = ETCInput.GetControlJoystick(DreamSpaceStates.JoystickName)
    assert( isNotNull(self.joystick), "cant find joystick: " .. DreamSpaceStates.JoystickName )
    ----

    self.joystick.onMoveStart:AddListener( Bind(self, self._OnMoveStart) )
    self.joystick.onMove:AddListener( function( _input )
        self:_OnMove( _input )
    end)
    self.joystick.onMoveEnd:AddListener( Bind(self, self._OnMoveEnd) )    


    -- ================= ui 按钮绑定 ===================:
    cs_coroutine.yield_return( ControllerMobileButtonsManager.WaitInstance() ) -- 等待实例化
    local controllerMobileButtonsManager = ControllerMobileButtonsManager.GetInstance()   -- 拿到唯一实例 -- !!! 允许为 nil
    if isNotNull(controllerMobileButtonsManager) then

        -- switch:
        self.OnSwitch = function()
            self.playerInputSwitcher:OnSwitch()
        end

        if isNotNull(controllerMobileButtonsManager.switchButton_1) then 
            controllerMobileButtonsManager.switchButton_1.onClick:AddListener( self.OnSwitch )
        end

        if isNotNull(controllerMobileButtonsManager.switchButton_2) then 
            controllerMobileButtonsManager.switchButton_2.onClick:AddListener( self.OnSwitch )
        end

        if isNotNull(controllerMobileButtonsManager.attackButton) then 
            controllerMobileButtonsManager.attackButton.onClick:AddListener( function()
                self.playerInputSwitcher:OnAttack()
            end )
        end

        if isNotNull(controllerMobileButtonsManager.jumpButton) then 
            controllerMobileButtonsManager.jumpButton.onClick:AddListener( function()
                self.playerInputSwitcher:OnJump()
            end )
        end

        if isNotNull(controllerMobileButtonsManager.catEyeButton) then 
            controllerMobileButtonsManager.catEyeButton.onClick:AddListener( function()
                self.playerInputSwitcher:OpenCatEyeVision()
            end )
        end

    end

end



