function TouchInputSwitchable:_OnMoveStart()
    InputManager.SetMoveInputFromDevice( Vector2.zero )
end


-- _input: x 表示向角色右, y表示向前
function TouchInputSwitchable:_OnMove(_input)
    --print( "touch input = " .. tostring( _input.magnitude )  )
    local mag = Mathf.Lerp( _input.magnitude, 1.0, 0.2 )
    local moveInput0 = _input.normalized * mag

    --InputManager.SetMoveInputFromDevice( newInput )

    if moveInput0.magnitude < 0.00001 then 
        print( "异常: joystick 传入的 位移量为 零向量 ..." ) -- todo: 在 pc editor 模式下, 且角色控制器启用了 mobile 模式时...
        self.switchablePlayerController:MoveEnd()
        return
    end 

    local rawInput = Vector3(moveInput0.x, 0, moveInput0.y)
    local cameraPlanarRotation = self.playerInputSwitcher:CalculateCameraDirection(self.mCamera.transform.rotation)
    local moveInput = cameraPlanarRotation * rawInput

    InputManager.SetMoveInputFromDevice( moveInput )
end


function TouchInputSwitchable:_OnMoveEnd()
    InputManager.SetMoveInputFromDevice( Vector2.zero )
end




return TouchInputSwitchable